import base64, os

out = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'output', '建築設計検討ツール')
os.makedirs(out, exist_ok=True)

PLAN_B64 = ""

BOUNDARY_B64 = ""

# パディングを自動補完してデコード
def safe_b64decode(s):
    s = s.strip()
    pad = len(s) % 4
    if pad:
        s += '=' * (4 - pad)
    return base64.b64decode(s)

plan_data = safe_b64decode(PLAN_B64)
with open(os.path.join(out, 'plan_editor.html'), 'wb') as f:
    f.write(plan_data)
print(f"plan_editor.html: {len(plan_data)} bytes")

boundary_data = safe_b64decode(BOUNDARY_B64)
with open(os.path.join(out, 'boundary_check.html'), 'wb') as f:
    f.write(boundary_data)
print(f"boundary_check.html: {len(boundary_data)} bytes")

print("Done!")
